"use strict";(self.webpackChunk_711=self.webpackChunk_711||[]).push([[764,960],{764(e,n,a){a.r(n),a.d(n,{default:()=>r}),a.dn(r);var i=a(540);function r(){return i.createElement("div",{className:"markdown",dangerouslySetInnerHTML:{__html:'<p>At the border of San Francisco&#39;s Districts 7 and 11, Ingleside is the\nneighborhood we lovingly call home.</p>\n<p>Volunteer with us to build a stronger Ingleside for everyone.</p>\n<p>Follow us on Instagram: <a href="https://instagram.com/711.ingleside">711.ingleside</a></p>\n<hr>\n<h1><a href="https://www.sfgoodneighborweek.org/">Good Neighbor Week</a>: Ingleside</h1>\n<h2>Saturday, 26 September, 8:00am-3:00pm</h2>\n<p>Join your Ingleside neighbors in kicking off <a href="https://www.sfgoodneighborweek.org/">Good Neighbor Week</a> with a\nfull day of neighborhood beautification work!</p>\n<ul>\n<li>8:00am-10:00am: Weeding near Balboa Park BART<ul>\n<li>Meet in the <a href="https://maps.app.goo.gl/qZsDMNAskB4nfc6F9">BART plaza, south of Geneva Ave</a></li>\n<li>Bring gloves, plant clippers, etc.</li>\n</ul>\n</li>\n<li>11:00am-12:00pm: Trash pickup<ul>\n<li>Meet at <a href="https://maps.app.goo.gl/YPnqurSzgpB4VcxC6">Ocean Ale House</a></li>\n<li>All supplies provided, including lunch afterwards!</li>\n</ul>\n</li>\n<li>2:00pm-3:00pm: Cigarette butt mitigation<ul>\n<li>Meet at <a href="https://maps.app.goo.gl/PgVsZ9DDPVzkRJ1F6">Unity Plaza</a></li>\n<li>Bring brooms and bags; we will have some too.</li>\n<li>Where feasible, we will try to hang cigarette butt disposal cans.</li>\n</ul>\n</li>\n</ul>\n<hr>\n<h1><a href="/workshops/">Ingleside Workshops</a></h1>\n<p>Free skill-sharing workshops led by neigborhood volunteers. Learn skills through\nhands-on activities, meet your neighbors, and win raffle prizes.</p>\n<p><a href="/workshops/">Click here to learn more and sign up!</a></p>\n<p>Presented in partnership with:</p>\n<ul>\n<li><a href="https://civicjoyfund.org/">Civic Joy Fund</a></li>\n<li><a href="https://oaacbd.org/">Ocean Avenue Association</a></li>\n</ul>\n<hr>\n<h1>Ingleside Trash Pickup</h1>\n<h2>Every Saturday, 11am @ <a href="https://maps.app.goo.gl/YPnqurSzgpB4VcxC6">Ocean Ale House</a></h2>\n<p>Since 2023, the Ingleside trash pickup has been happening every Saturday at 11am\nsharp, rain or shine. Meet us in front of Ocean Ale House for an hour of trash\ncollection, followed by lunch and merriment. Trash bags, grabbers, rings, safety\nvests, and gloves are all provided. Sponsored by:</p>\n<ul>\n<li><a href="https://civicjoyfund.org/projects/clean-up-the-city">Civic Joy Fund</a></li>\n<li><a href="https://cleanupthecity.org/">Clean Up The City</a></li>\n<li><a href="https://refuserefusesf.org/">Refuse Refuse SF</a></li>\n<li><a href="https://sfpublicworks.org/get_involved/adopt-street-program">SF Public Works: Adopt-A-Street</a></li>\n</ul>\n'}})}},960(e,n,a){a.r(n),a.d(n,{default:()=>l});var i=a(540),r=a(764);function l(){return i.createElement(i.Fragment,null,i.createElement("div",{className:"hero-h1uJx"},i.createElement("div",{className:"logo-EQV4J"})),i.createElement(r.default,null))}}}]);
